import java.io.BufferedReader;
import java.io.InputStreamReader;

public class CF_630_D2_E_Variant3 {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        long n = Long.parseLong(input[0]);
        long m = Long.parseLong(input[1]);
        int L = Integer.parseInt(input[2]);
        int R = Integer.parseInt(input[3]);

        long mod = 998244353;
        long inv2 = powerMod(2, mod - 2, mod);
        long diff = R - L + 1;
        long p1 = diff / 2;
        long p2 = diff - p1;
        long answer;

        if ((n * m) % 2 == 1) {
            answer = powerMod(diff, n * m, mod);
        } else {
            long p1Total = diff;
            long p2Total = Math.abs(p1 - p2);
            long option1 = powerMod(p1Total, n * m, mod);
            long option2 = powerMod(p2Total, n * m, mod);
            long total = (option1 + option2) % mod;
            answer = (total * inv2) % mod;
        }
        System.out.println(answer);
    }

    static long powerMod(long base, long exp, long mod) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}
